+<?php
+declare(strict_types=1);
+
+function interne_notizen_laden(): array
+{
+    $db = datenbank_verbindung();
+    if (!$db) {
+        return [];
+    }
+
+    $abfrage = $db->query('SELECT * FROM interne_notizen ORDER BY geaendert_am DESC');
+    return $abfrage->fetchAll() ?: [];
+}
+
+function interne_notiz_laden(int $id): ?array
+{
+    $db = datenbank_verbindung();
+    if (!$db) {
+        return null;
+    }
+
+    $abfrage = $db->prepare('SELECT * FROM interne_notizen WHERE id = :id LIMIT 1');
+    $abfrage->execute(['id' => $id]);
+    return $abfrage->fetch() ?: null;
+}
+
+function interne_notiz_erstellen(array $daten): bool
+{
+    $db = datenbank_verbindung();
+    if (!$db) {
+        return false;
+    }
+
+    $jetzt = time();
+    $abfrage = $db->prepare('INSERT INTO interne_notizen (titel, inhalt, prioritaet, status, erstellt_am, geaendert_am) VALUES (:titel, :inhalt, :prioritaet, :status, :erstellt_am, :geaendert_am)');
+    return $abfrage->execute([
+        'titel' => $daten['titel'] ?? '',
+        'inhalt' => $daten['inhalt'] ?? '',
+        'prioritaet' => $daten['prioritaet'] ?? 'normal',
+        'status' => $daten['status'] ?? 'offen',
+        'erstellt_am' => $jetzt,
+        'geaendert_am' => $jetzt,
+    ]);
+}
+
+function interne_notiz_bearbeiten(int $id, array $daten): bool
+{
+    $db = datenbank_verbindung();
+    if (!$db) {
+        return false;
+    }
+
+    $jetzt = time();
+    $abfrage = $db->prepare('UPDATE interne_notizen SET titel = :titel, inhalt = :inhalt, prioritaet = :prioritaet, status = :status, geaendert_am = :geaendert_am WHERE id = :id');
+    return $abfrage->execute([
+        'id' => $id,
+        'titel' => $daten['titel'] ?? '',
+        'inhalt' => $daten['inhalt'] ?? '',
+        'prioritaet' => $daten['prioritaet'] ?? 'normal',
+        'status' => $daten['status'] ?? 'offen',
+        'geaendert_am' => $jetzt,
+    ]);
+}
+
+function interne_notiz_loeschen(int $id): bool
+{
+    $db = datenbank_verbindung();
+    if (!$db) {
+        return false;
+    }
+
+    $abfrage = $db->prepare('DELETE FROM interne_notizen WHERE id = :id');
+    return $abfrage->execute(['id' => $id]);
+}
+
+function interne_notiz_status_aendern(int $id, string $neuer_status): bool
+{
+    $db = datenbank_verbindung();
+    if (!$db) {
+        return false;
+    }
+
+    $jetzt = time();
+    $abfrage = $db->prepare('UPDATE interne_notizen SET status = :status, geaendert_am = :geaendert_am WHERE id = :id');
+    return $abfrage->execute([
+        'id' => $id,
+        'status' => $neuer_status,
+        'geaendert_am' => $jetzt,
+    ]);
+}

