+<?php
+/*
+ICON: file-check
+TITLE: Status ändern
+PRIO: 54
+BEREICH: work
+RECHT: interne_notizen_bearbeiten
+*/
+
+if (!rechte_pruefen('interne_notizen_bearbeiten')) {
+    http_response_code(403);
+    exit('Zugriff verweigert');
+}
+
+$id = (int)($_GET['id'] ?? 0);
+$neuer_status = $_GET['status'] ?? '';
+
+// Gültige Statuswerte
+$gueltige_status = ['offen', 'erledigt'];
+if (!in_array($neuer_status, $gueltige_status, true)) {
+    http_response_code(400);
+    exit('Ungültiger Status');
+}
+
+$notiz = interne_notiz_laden($id);
+
+if (!$notiz) {
+    http_response_code(404);
+    exit('Notiz nicht gefunden');
+}
+
+// CSRF-Token prüfen
+if (!isset($_SESSION['csrf_token']) || ($_GET['csrf_token'] ?? '') !== $_SESSION['csrf_token']) {
+    http_response_code(403);
+    exit('Ungültiger Sicherheits-Token');
+}
+
+// Status ändern
+if (interne_notiz_status_aendern($id, $neuer_status)) {
+    // Erfolg - Weiterleiten zur Übersicht
+    header('Location: index.php?seite=work_interne_notizen');
+    exit();
+} else {
+    http_response_code(500);
+    exit('Fehler beim Ändern des Status');
+}

